#!/usr/bin/env python3
# ############################################################################
# SYNTHETIC DATA — every value in the output CSV is generated by a seeded RNG.
# This file produces data/risklabs_synthetic.csv for the RiskLabs COLLEGE
# PROTOTYPE only. Nothing here is real company data; do not treat any row as
# describing a real firm. Used to validate the ML pipeline end-to-end.
# ############################################################################
"""Generate the synthetic RiskLabs dataset (data/risklabs_synthetic.csv).

SYNTHETIC DATA — all 1200 companies are fictitious, produced with
np.random.default_rng(42) so reruns are byte-identical.

TRANSPARENT GENERATION RULE (also printed on every run):
  1. Sample a latent risk tier per company: low (40%), medium (35%), high (25%).
  2. Generate the 9 financial columns (in Rs. crore) CONDITIONED on the tier:
     - risky tiers -> higher debt share of assets, lower net-profit margins,
       weaker/negative operating cash flow, lower current ratios.
     - safe tiers   -> low debt share, healthy margins, strong cash flow,
       comfortable current ratios.
     Identities are kept plausible (total_liabilities < total_assets, etc.).
  3. Generate report_text from template sentence pools (3-8 sentences):
     - risky tiers draw mostly from a risk-sentence pool whose sentences embed
       exact phrases from src/nlp.py LEXICON (e.g. "cash crunch",
       "covenant breach", "going concern");
     - safe tiers draw mostly from a positive-sentence pool with healthy
       language (e.g. "stable demand", "robust balance sheet").
     - all tiers include some neutral boilerplate sentences.
  4. Compute risk_label from a FIXED weighted score of ratios + text signals:
       risk_score =
           25 * clip((debt_to_equity - 0.5) / 2.5, 0, 1)
         + 20 * clip((1.5 - current_ratio) / 1.5, 0, 1)
         + 20 * clip((0.05 - net_profit_margin) / 0.30, 0, 1)
         + 15 * clip((0.05 - roa) / 0.25, 0, 1)
         + 10 * clip((0.15 - ocf_to_debt) / 0.75, 0, 1)
         + 10 * clip(lex_total / 6.0, 0, 1)
       where lex_total is the lexicon score from extract_lexicon_features
       (negative weights for positive language, clipped at 0 here).
       Label thresholds: score < 15 -> Low; score < 45 -> Medium; else High.
     Note the label is a deterministic function of the generated observables
     (not of the latent tier), so the classification task is learnable.
"""

import sys
from pathlib import Path

import numpy as np
import pandas as pd

BASE_DIR = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(BASE_DIR))

from src.features import compute_ratios  # noqa: E402
from src.nlp import extract_lexicon_features  # noqa: E402

N_COMPANIES = 1200
SEED = 42
OUT_PATH = BASE_DIR / "data" / "risklabs_synthetic.csv"

FIN_COLS = [
    "revenue",
    "net_profit",
    "total_assets",
    "total_liabilities",
    "total_debt",
    "equity",
    "current_assets",
    "current_liabilities",
    "operating_cash_flow",
]

RULES_TEXT = """\
LABEL RULE (weighted risk score, thresholds fixed):
  risk_score =
      25 * clip((debt_to_equity - 0.5) / 2.5, 0, 1)
    + 20 * clip((1.5 - current_ratio) / 1.5, 0, 1)
    + 20 * clip((0.05 - net_profit_margin) / 0.30, 0, 1)
    + 15 * clip((0.05 - roa) / 0.25, 0, 1)
    + 10 * clip((0.15 - ocf_to_debt) / 0.75, 0, 1)
    + 10 * clip(lex_total / 6.0, 0, 1)
  Low: score < 15 | Medium: 15 <= score < 45 | High: score >= 45
Latent tiers (drive financials + text only): low 40% / medium 35% / high 25%."""

NEUTRAL_SENTENCES = [
    "The financial statements have been prepared in accordance with applicable accounting standards.",
    "Management remains focused on operational efficiency and cost discipline.",
    "The board reviewed the company's performance for the financial year.",
    "Key markets showed mixed trends during the year under review.",
    "The company continued to invest in technology and process improvement.",
    "Employee strength and attrition remained broadly stable.",
]

RISKY_SENTENCES = [
    "The company faces a liquidity concern as operating cash reserves declined through the year.",
    "Management acknowledged a cash crunch in the fourth quarter.",
    "A liquidity squeeze forced the company to draw on emergency credit lines.",
    "Working capital pressure intensified after delayed payments from key customers.",
    "Cash flow strain affected vendor payments during the second half.",
    "A debt default event was disclosed in the notes to the accounts.",
    "The company recorded a payment default on a portion of its term borrowings.",
    "The auditors flagged a covenant breach on certain loan facilities.",
    "The company remains overleveraged relative to its earnings capacity.",
    "Refinancing risk remains elevated as large debt maturities fall due next year.",
    "The growing debt burden limits the company's financial flexibility.",
    "Mounting losses have steadily eroded the company's net worth.",
    "Declining revenue in core segments weighed on overall performance.",
    "A sharp revenue decline in the second half offset earlier gains.",
    "Falling margins and eroding profitability hurt operating results.",
    "Margin compression from input-cost inflation squeezed operating profit.",
    "Ongoing litigation and a pending lawsuit create material contingent liabilities.",
    "A regulatory probe into past disclosures is currently underway.",
    "The statutory auditor issued an auditor qualification on internal financial controls.",
    "A penalty imposed by the regulator dented the quarter's profitability.",
    "A regulatory action against a subsidiary added to compliance costs.",
    "The auditor highlighted a material uncertainty around the going concern assumption.",
    "Continued stress has raised concerns about a possible bankruptcy filing.",
    "Creditors warned of insolvency proceedings if restructuring talks fail.",
    "The board approved a plan to cease operations in non-viable business units.",
    "An operational creditor filed a winding up petition against the company.",
]

POSITIVE_SENTENCES = [
    "Stable demand across core markets supported steady revenue growth.",
    "A strong order book provides healthy revenue visibility for next year.",
    "Healthy cash generation comfortably funded capital expenditure.",
    "The company maintains a robust balance sheet with conservative financial policies.",
    "A record profit was reported on the back of operating leverage.",
    "Continued debt reduction has strengthened the company's credit profile.",
    "The company enjoys a strong liquidity position with ample undrawn limits.",
    "Low leverage gives the company headroom to fund future growth.",
    "Diversified revenue streams reduced dependence on any single customer.",
    "Prudent working capital management shortened the cash conversion cycle.",
]


def _tiered(rng, is_low, is_med, is_high, low_fn, med_fn, high_fn, size):
    out = np.empty(size)
    out[is_low] = low_fn(int(is_low.sum()))
    out[is_med] = med_fn(int(is_med.sum()))
    out[is_high] = high_fn(int(is_high.sum()))
    return out


def generate_financials(rng, n):
    tier = rng.choice(["low", "medium", "high"], size=n, p=[0.40, 0.35, 0.25])
    is_low, is_med, is_high = tier == "low", tier == "medium", tier == "high"

    revenue = rng.lognormal(mean=np.log(900.0), sigma=0.85, size=n)
    revenue *= np.where(is_low, 1.25, np.where(is_med, 1.0, 0.75))
    revenue = np.clip(revenue, 50.0, 30000.0)

    margin = _tiered(
        rng, is_low, is_med, is_high,
        lambda k: rng.normal(0.12, 0.04, k),
        lambda k: rng.normal(0.03, 0.035, k),
        lambda k: rng.normal(-0.06, 0.06, k),
        n,
    )
    margin = np.clip(margin, -0.60, 0.40)
    net_profit = margin * revenue

    total_assets = revenue * rng.uniform(0.6, 1.4, n)

    debt_share = _tiered(
        rng, is_low, is_med, is_high,
        lambda k: rng.uniform(0.05, 0.25, k),
        lambda k: rng.uniform(0.30, 0.55, k),
        lambda k: rng.uniform(0.60, 0.90, k),
        n,
    )
    total_debt = total_assets * debt_share
    other_liab = total_assets * rng.uniform(0.05, 0.20, n)
    total_liabilities = total_debt + other_liab
    # Keep total_liabilities strictly below total_assets (plausible balance sheet).
    scale = np.minimum(1.0, 0.95 * total_assets / total_liabilities)
    total_debt *= scale
    total_liabilities *= scale
    equity = total_assets - total_liabilities

    current_liabilities = total_liabilities * rng.uniform(0.20, 0.50, n)
    target_cr = _tiered(
        rng, is_low, is_med, is_high,
        lambda k: np.clip(rng.normal(2.2, 0.5, k), 1.2, 4.0),
        lambda k: np.clip(rng.normal(1.15, 0.25, k), 0.6, 2.5),
        lambda k: np.clip(rng.normal(0.70, 0.20, k), 0.3, 1.5),
        n,
    )
    current_assets = np.minimum(target_cr * current_liabilities, 0.70 * total_assets)

    ocf_margin = _tiered(
        rng, is_low, is_med, is_high,
        lambda k: rng.normal(0.10, 0.04, k),
        lambda k: rng.normal(0.03, 0.04, k),
        lambda k: rng.normal(-0.04, 0.06, k),
        n,
    )
    ocf_margin = np.clip(ocf_margin, -0.50, 0.40)
    operating_cash_flow = ocf_margin * revenue

    df = pd.DataFrame(
        {
            "revenue": revenue,
            "net_profit": net_profit,
            "total_assets": total_assets,
            "total_liabilities": total_liabilities,
            "total_debt": total_debt,
            "equity": equity,
            "current_assets": current_assets,
            "current_liabilities": current_liabilities,
            "operating_cash_flow": operating_cash_flow,
        }
    )
    return df.round(2), tier


def generate_texts(rng, tier):
    texts = []
    for t in tier:
        if t == "low":
            n_neu, n_pos, n_risk = rng.integers(1, 3), rng.integers(2, 5), rng.integers(0, 2)
        elif t == "medium":
            n_neu, n_pos, n_risk = rng.integers(1, 3), rng.integers(0, 3), rng.integers(2, 4)
        else:
            n_neu, n_pos, n_risk = rng.integers(1, 3), rng.integers(0, 2), rng.integers(3, 6)
        sents = (
            list(rng.choice(NEUTRAL_SENTENCES, size=n_neu, replace=False))
            + list(rng.choice(POSITIVE_SENTENCES, size=n_pos, replace=False))
            + list(rng.choice(RISKY_SENTENCES, size=n_risk, replace=False))
        )
        rng.shuffle(sents)
        texts.append(" ".join(sents))
    return texts


def compute_labels(fin_df, texts):
    ratios = compute_ratios(fin_df)
    lex = extract_lexicon_features(texts)
    score = (
        25 * np.clip((ratios["debt_to_equity"] - 0.5) / 2.5, 0, 1)
        + 20 * np.clip((1.5 - ratios["current_ratio"]) / 1.5, 0, 1)
        + 20 * np.clip((0.05 - ratios["net_profit_margin"]) / 0.30, 0, 1)
        + 15 * np.clip((0.05 - ratios["roa"]) / 0.25, 0, 1)
        + 10 * np.clip((0.15 - ratios["ocf_to_debt"]) / 0.75, 0, 1)
        + 10 * np.clip(lex["lex_total"] / 6.0, 0, 1)
    )
    labels = np.where(score < 15, "Low", np.where(score < 45, "Medium", "High"))
    return labels, score


def main():
    rng = np.random.default_rng(SEED)
    fin_df, tier = generate_financials(rng, N_COMPANIES)
    texts = generate_texts(rng, tier)
    labels, score = compute_labels(fin_df, texts)

    df = fin_df.copy()
    df.insert(0, "company_id", [f"SYN-{i:04d}" for i in range(1, N_COMPANIES + 1)])
    df["report_text"] = texts
    df["risk_label"] = labels

    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(OUT_PATH, index=False)

    print("=" * 70)
    print("RiskLabs SYNTHETIC dataset generator — all data below is fictitious.")
    print("=" * 70)
    print(RULES_TEXT)
    print("-" * 70)
    print(f"Rows written : {len(df)} -> {OUT_PATH}")
    print("Label distribution (risk_label):")
    dist = df["risk_label"].value_counts()
    for lbl in ["Low", "Medium", "High"]:
        c = int(dist.get(lbl, 0))
        print(f"  {lbl:6s}: {c:4d} ({c / len(df):5.1%})")
    print(f"Mean risk score: {score.mean():.1f} | min {score.min():.1f} | max {score.max():.1f}")
    print("NOTE: SYNTHETIC data for pipeline validation only — not real companies.")


if __name__ == "__main__":
    main()
